<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'URL Encoder & Decoder','description'=>'Encode or decode URLs safely in your browser.','url'=>'https://smarttoolz.in/tools/url-encoder/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>URL Encoder & Decoder</h1><p>Encode special URL characters or decode encoded URLs.</p><textarea id="i" placeholder="Enter URL or text"></textarea><button id="e">Encode</button><button id="d">Decode</button><textarea id="o" readonly placeholder="Result"></textarea></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool textarea{width:100%;min-height:130px;box-sizing:border-box;margin:8px 0;padding:14px;border:1px solid #ddd;border-radius:12px}.tool button{padding:11px 16px;margin:5px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}</style><script>const i=document.getElementById('i'),o=document.getElementById('o');e.onclick=()=>o.value=encodeURIComponent(i.value);d.onclick=()=>{try{o.value=decodeURIComponent(i.value)}catch(x){o.value='Invalid encoded text.'}}</script><?php smarttoolz_tool_page_end(); ?>